INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('aa400001-cc00-0000-0000-000000000001', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Essaouira Windsurf Lesson', 'A 2-hour windsurf lesson on Essaouira bay, famous for its consistent wind. Gear included.', ARRAY['en','fr','es','ary-Latn'], 12, 3, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/18554039/pexels-photo-18554039.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400002-cc00-0000-0000-000000000002', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Essaouira Argan Forest Walk', 'A guided walk through the argan forests south of Essaouira, with a visit to a cooperative.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 2, '{}', 1, 8, 150, 1, 'active', 'https://images.pexels.com/photos/9756598/pexels-photo-9756598.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400003-cc00-0000-0000-000000000003', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Essaouira Island Boat Trip', 'A boat trip to Essaouira Island (Mogador), a nature reserve with ruins and birdlife.', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/6662921/pexels-photo-6662921.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400004-cc00-0000-0000-000000000004', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Essaouira Surf & Turf Day', 'A morning surf lesson and afternoon guided medina walk — the perfect Essaouira combo.', ARRAY['en','fr','es','ary-Latn'], 10, 2, '{}', 1, 6, 360, 2, 'active', 'https://images.pexels.com/photos/34855136/pexels-photo-34855136.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400005-cc00-0000-0000-000000000005', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Essaouira Sunset Coastal Walk', 'A guided sunset walk along the ramparts and coast, ending at the Skala du Port.', ARRAY['en','fr','es','ary-Latn'], 6, 1, '{}', 1, 12, 90, 1, 'active', 'https://images.pexels.com/photos/33414237/pexels-photo-33414237.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400006-cc00-0000-0000-000000000006', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Essaouira Tagine Dinner', 'A traditional Moroccan tagine dinner at a medina restaurant, with salad, dessert and tea.', ARRAY['en','fr','ary-Latn','ber'], 8, 1, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/36984667/pexels-photo-36984667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400007-cc00-0000-0000-000000000007', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Essaouira Couscous Friday Lunch', 'A traditional Friday couscous lunch, as Moroccans eat it, at a medina guesthouse.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 8, 90, 2, 'active', 'https://images.pexels.com/photos/36916123/pexels-photo-36916123.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400008-cc00-0000-0000-000000000008', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Essaouira Rooftop Breakfast', 'A Moroccan breakfast on a medina rooftop — msemen, beghrir, honey, olive oil and mint tea.', ARRAY['en','fr','es','ary-Latn','ber'], 5, 1, '{}', 1, 10, 60, 1, 'active', 'https://images.pexels.com/photos/30906051/pexels-photo-30906051.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400009-cc00-0000-0000-000000000009', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Essaouira Wine & Tapas Evening', 'An evening of Moroccan tapas and local wine at a stylish medina bar.', ARRAY['en','fr','es','ary-Latn'], 18, 1, '{}', 2, 10, 120, 3, 'active', 'https://images.pexels.com/photos/18077172/pexels-photo-18077172.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000a-cc00-0000-0000-00000000000a', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Riad Mogador Garden Room (per night)', 'A garden room in a medina riad with shared courtyard and breakfast.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 3, 1440, 2, 'active', 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000b-cc00-0000-0000-00000000000b', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Essaouira Beachfront Villa (per night)', 'A private beachfront villa 5 minutes from the medina, sleeping up to 6, with pool.', ARRAY['en','fr','es','ary-Arab'], 0, 1, '{}', 1, 6, 1440, 4, 'active', 'https://images.pexels.com/photos/15531178/pexels-photo-15531178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000c-cc00-0000-0000-00000000000c', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Essaouira Surf Hostel (per night)', 'A budget surf hostel near the beach with dorm beds, board storage and breakfast.', ARRAY['en','fr','es','ary-Latn'], 0, 1, '{}', 1, 8, 1440, 1, 'active', 'https://images.pexels.com/photos/25254928/pexels-photo-25254928.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000d-cc00-0000-0000-00000000000d', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Essaouira Jewish Mellah Tour', 'A guided tour of the historic Jewish Quarter of Essaouira, once a thriving multicultural community.', ARRAY['en','fr','es','ary-Latn'], 10, 1, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/19280616/pexels-photo-19280616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000e-cc00-0000-0000-00000000000e', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Essaouira Art Galleries Walk', 'A guided walk through Essaouira''s contemporary art galleries, from Gallerie Damgaard to local studios.', ARRAY['en','fr','es','ary-Latn'], 10, 1, '{}', 1, 8, 120, 2, 'active', 'https://images.pexels.com/photos/22711558/pexels-photo-22711558.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa40000f-cc00-0000-0000-00000000000f', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Essaouira Painting Workshop', 'Paint with local artist supplies, inspired by Essaouira''s light and colours. Canvas to take home.', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 6, 120, 1, 'active', 'https://images.pexels.com/photos/32422996/pexels-photo-32422996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400010-cc00-0000-0000-000000000010', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Essaouira Cooking Class', 'Learn to cook Moroccan fish tagine and seafood pastilla, with a market visit and lunch.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 1, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/6223144/pexels-photo-6223144.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400011-cc00-0000-0000-000000000011', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Essaouira Music Workshop', 'Learn to play the guembri (Gnawa bass) with a local musician in a medina music shop.', ARRAY['en','fr','es','ary-Latn'], 10, 1, '{}', 1, 6, 90, 1, 'active', 'https://images.pexels.com/photos/12585023/pexels-photo-12585023.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa400012-cc00-0000-0000-000000000012', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Essaouira Sail-Making Workshop', 'Visit the last traditional sail-making workshop in the port and learn the craft of canvas sails.', ARRAY['en','fr','ary-Latn'], 12, 2, '{}', 1, 4, 90, 1, 'active', 'https://images.pexels.com/photos/6662921/pexels-photo-6662921.jpeg?auto=compress&cs=tinysrgb&h=650&w=940')
